function lines(s){return s.replace(/\r/g,'').split('\n');}
function lcs(a,b){
  var m=a.length,n=b.length;
  if(m*n>4000000){return null;}
  var d=[];
  for(var i=0;i<=m;i++){d.push(new Uint32Array(n+1));}
  for(i=1;i<=m;i++){
    for(var j=1;j<=n;j++){
      d[i][j]=a[i-1]===b[j-1]?d[i-1][j-1]+1:Math.max(d[i-1][j],d[i][j-1]);
    }
  }
  var out=[],x=m,y=n;
  while(x>0&&y>0){
    if(a[x-1]===b[y-1]){out.push({t:'same',v:a[x-1]});x--;y--;}
    else if(d[x-1][y]>=d[x][y-1]){out.push({t:'del',v:a[x-1]});x--;}
    else {out.push({t:'add',v:b[y-1]});y--;}
  }
  while(x>0){out.push({t:'del',v:a[x-1]});x--;}
  while(y>0){out.push({t:'add',v:b[y-1]});y--;}
  return out.reverse();
}
function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
document.getElementById('go').addEventListener('click',function(){
  var A=document.getElementById('a').value,B=document.getElementById('b').value;
  var note=document.getElementById('note');
  if(!A&&!B){note.textContent='Paste some text into both boxes first.';return;}
  var res=lcs(lines(A),lines(B));
  if(!res){note.textContent='Those texts are too large to compare line by line. Try smaller sections.';return;}
  var add=0,del=0,same=0,html='';
  res.forEach(function(r){
    if(r.t==='add'){add++;html+='<div class="dline dadd"><span class="mk">+</span><span>'+esc(r.v)+'</span></div>';}
    else if(r.t==='del'){del++;html+='<div class="dline ddel"><span class="mk">-</span><span>'+esc(r.v)+'</span></div>';}
    else {same++;html+='<div class="dline dsame"><span class="mk"> </span><span>'+esc(r.v)+'</span></div>';}
  });
  document.getElementById('sAdd').textContent=add;
  document.getElementById('sDel').textContent=del;
  document.getElementById('sSame').textContent=same;
  document.getElementById('stats').style.display='';
  var box=document.getElementById('diff');box.innerHTML=html;box.style.display='';
  note.textContent=(add||del)?'Found '+add+' added and '+del+' removed lines.':'The two texts are identical.';
  WT.resize();
});
document.getElementById('clear').addEventListener('click',function(){
  document.getElementById('a').value='';document.getElementById('b').value='';
  document.getElementById('diff').style.display='none';
  document.getElementById('stats').style.display='none';
  document.getElementById('note').textContent='Paste two versions of a text and press Compare.';
  WT.resize();
});
